 useEffect(()=>{const handler=(event:KeyboardEvent)=>{const target=event.target as HTMLElement|null;if(target?.closest("input,textarea,select,[contenteditable=true]"))return;const mod=event.metaKey||event.ctrlKey;if(mod&&event.key.toLowerCase()==="z"){event.preventDefault();if(event.shiftKey)redo();else undo()}else if(mod&&event.key.toLowerCase()==="y"){event.preventDefault();redo()}else if(event.key===" "){event.preventDefault();if(player.current){if(playing)player.current.pause();else player.current.play()}}else if((event.key==="Delete"||event.key==="Backspace")&&selectedClip){event.preventDefault();patch({clips:removeClip(ensureClips(),selectedClip)});setSelectedClip(null)}};window.addEventListener("keydown",handler);return()=>window.removeEventListener("keydown",handler)},[playing,selectedClip,settings,canUndo,canRedo]);
